@Component({
    selector: 'app-form-datos-bancarios',
    imports: [
    FormsModule
],
    templateUrl: './form-datos-bancarios.component.html',
    styleUrl: './form-datos-bancarios.component.css'
})
export class FormDatosBancariosComponent {
  credito?: Credito

  isFormalizado:boolean = false
  readonly bancosList = institucionesFinancieras


  // Lista filtrada
  filteredBancos: string[] = [];

  constructor(
    public creditoController: CreditoService,
    private utils: UtilsService,
    private route: ActivatedRoute,
    private creditoUtils : CreditoFormUtilsService,
  ) { }

  ngOnInit() {
    this.route.parent?.parent?.paramMap.subscribe(async (params) => {
      const id = this.utils.intOrNull(params.get('credito_id'))
      if (id) {
        this.credito = await this.creditoController.find(id, [])
        this.isFormalizado = this.creditoUtils.isFormDisabled(this.credito)
      }
    })
  }

  // Filtra bancos según lo que escribe el usuario
  filterBancos() {
    if(!this.credito) return;
    const searchTerm = this.credito.banco?.toLowerCase() || '';
    this.filteredBancos = this.bancosList.filter( banco =>
      banco.toLowerCase().includes(searchTerm)
    ).slice(0, 10);
  }

  // Selecciona un banco de la lista
  selectBanco(banco: string) {
    if(!this.credito) return;
    this.credito.banco = banco;
    this.filteredBancos = []; // Oculta la lista
  }
}
