import { Injectable } from '@angular/core';
import { Credito } from "../../../models/credito.model";

/**
 * Clase creada con el propósito de reutilizar código y reglas en los formularios de créditos.
 */
@Injectable({
  providedIn: 'root'
})
export class CreditoFormUtilsService {

    isFormDisabled(credito: Credito|undefined):boolean {
      if(!credito) return false;
      return credito.formalizado_fecha !== null
    }
}